//! The OpenAPI fixtures in `conformance/fixtures/`, generated by
//! `conformance/fixture-generator/` and committed.

/// The main service: users, rate limits, `x-router-path` forms, security, bodies.
pub const USERS_SERVICE: &str = include_str!("../../fixtures/users-service.json");
/// `USERS_SERVICE` plus `GET /v2/new`, for swapping documents at runtime.
pub const USERS_SERVICE_V2: &str = include_str!("../../fixtures/users-service-v2.json");
/// The second service, for the Default Service and Direct Prefix cases.
pub const DEFAULT_SERVICE: &str = include_str!("../../fixtures/default-service.json");
/// A document with a path-level `parameters` key, which the reference fails to load.
pub const INVALID_PATH_ITEM: &str = include_str!("../../fixtures/invalid-path-item.json");

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn fixtures_are_json_with_paths() {
        for fixture in [
            USERS_SERVICE,
            USERS_SERVICE_V2,
            DEFAULT_SERVICE,
            INVALID_PATH_ITEM,
        ] {
            let doc: serde_json::Value = serde_json::from_str(fixture).unwrap();
            assert!(doc["paths"].is_object());
        }
    }

    #[test]
    fn a_literal_path_follows_a_parameterised_one() {
        let doc: serde_json::Value = serde_json::from_str(USERS_SERVICE).unwrap();
        let paths: Vec<&String> = doc["paths"].as_object().unwrap().keys().collect();
        let param = paths.iter().position(|p| *p == "/v1/users/{id}").unwrap();
        let literal = paths.iter().position(|p| *p == "/v1/users/me").unwrap();
        assert!(param < literal);
    }
}
